ALTER TABLE orders ADD COLUMN IF NOT EXISTS discount_amount integer NOT NULL DEFAULT 0 CHECK (discount_amount >= 0);
ALTER TABLE orders ADD COLUMN IF NOT EXISTS voucher_code varchar(64);
CREATE TABLE IF NOT EXISTS vouchers (id varchar(36) PRIMARY KEY, target_type varchar(16) NOT NULL CHECK (target_type IN ('event','shop')), target_id varchar NOT NULL, code varchar(64) NOT NULL, discount_type varchar(16) NOT NULL CHECK (discount_type IN ('fixed','percentage')), discount_value integer NOT NULL CHECK (discount_value > 0), max_discount integer NOT NULL DEFAULT 0 CHECK (max_discount >= 0), min_order_amount integer NOT NULL DEFAULT 0 CHECK (min_order_amount >= 0), usage_limit integer NOT NULL DEFAULT 0 CHECK (usage_limit >= 0), usage_per_user integer NOT NULL DEFAULT 1 CHECK (usage_per_user >= 0), used_count integer NOT NULL DEFAULT 0 CHECK (used_count >= 0), starts_at timestamptz, ends_at timestamptz, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(target_type, target_id, code), CHECK (ends_at IS NULL OR starts_at IS NULL OR ends_at > starts_at), CHECK (discount_type <> 'percentage' OR discount_value <= 100));
CREATE TABLE IF NOT EXISTS voucher_redemptions (id varchar(36) PRIMARY KEY, voucher_id varchar(36) NOT NULL REFERENCES vouchers(id), order_id varchar NOT NULL REFERENCES orders(id), user_id varchar NOT NULL REFERENCES users(id), discount_amount integer NOT NULL, released_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(order_id));
CREATE INDEX IF NOT EXISTS idx_voucher_redemptions_user ON voucher_redemptions(voucher_id,user_id) WHERE released_at IS NULL;
